        lock_path = self._get_lock_path(filepath)
        start_time = time.time()

        while True:
            try:
                fd = os.open(lock_path, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
                with os.fdopen(fd, 'w') as f:
                    f.write(agent_id)

